    print_right("峰值dBFS", 9);
    print_right("RMSdBFS", 8);
    print_right("波峰因数", 9);
    print_right("钳位", 9);
    print_right("匹配增益", 9);
    print_right("波形残差dB", 12);
    print_right("互调残差dB", 12);
