cat > /tmp/tp_sinc_check.c << 'EOF'
/* sinc 验证：满幅正弦 vs 满幅方波，校验 dBTP 读数与 BS.1770-4 行为一致 */
#include <stdio.h>
#include <math.h>
#include <stdlib.h>
#define PI 3.14159265358979323846
double truepeak_dbtp(const float *x, int n);
int main(void)
{
    int fs = 48000, N = fs, i;
    float *x = malloc((size_t)N * sizeof(float));
    double pk, dbtp;

    /* 满幅正弦 997 Hz，相位使峰落在采样点上 */
    for (i = 0; i < N; i++)
        x[i] = (float)(1.0 * sin(2.0*PI*997.0*i/fs + PI/2));
    dbtp = truepeak_dbtp(x, N);
    printf("满幅正弦 997Hz (峰在采样点): dBTP = %+.3f dB   预期 ~0.0\n", dbtp);

    /* 满幅方波 1 kHz：重建峰 4/pi = +2.10 dB（理想 sinc）；48 阶 FIR 限带后略低 */
    for (i = 0; i < N; i++)
        x[i] = (i % 48 < 24) ? 1.0f : -1.0f;
    dbtp = truepeak_dbtp(x, N);
    printf("满幅方波 1kHz (重建峰 4/pi): dBTP = %+.3f dB   预期 ~+2.0 (理想 sinc +2.10)\n", dbtp);

    /* 半采样偏移正弦：峰必然在采样点之间 —— 典型 ISP 场景 */
    for (i = 0; i < N; i++)
        x[i] = (float)(1.0 * sin(2.0*PI*997.0*i/fs));
    pk = 0.0;
    for (i = 0; i < N; i++) if (fabs(x[i]) > pk) pk = fabs(x[i]);
    dbtp = truepeak_dbtp(x, N);
    printf("满幅正弦 (峰间随机相位)  : dBTP = %+.3f dB   采样峰 %.3f (%.2f dBFS)\n",
           dbtp, pk, 20.0*log10(pk));
    free(x);
    return 0;
}
EOF
cc -O2 -std=c99 -Wall -Wextra -pedantic -I. /tmp/tp_sinc_check.c src/truepeak.c -lm -o /tmp/tp_sinc_check && /tmp/tp_sinc_check

